news = json.load(open(NEWS, encoding='utf-8'))
done = {n['title'][:60] for n in news}
add = []
for it in ITEMS:
    it['window'] = 'close'
    if it['title'][:60] in done:
        print('SKIP(已存在):', it['title'][:40])
        continue
    add.append(it)
news.extend(add)
json.dump(news, open(NEWS, 'w', encoding='utf-8'), ensure_ascii=False, indent=1)
print(f'\n新增 {len(add)} 条，news 总数 {len(news)}')
from collections import Counter
print(Counter(i['track'] for i in add))
